INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(109913, 'ruRU', '', 'Всегда, но к чему предупреждение?', 24330),
(110028, 'ruRU', '', 'Не вижу ничего необычного в этой жаровне. Выглядит довольно неплохо для такой древней вещи.', 24330),
(110100, 'ruRU', '', 'Та Жемчужина Тайной Премудрости, которую ты нашёл, весьма впечатляет. Я принёс старую книгу заклинаний, которую забрал у довольно неприятного вурдалака в Мертхольме. Он даже не понял, что его настигло. Ха!', 24330),
(110101, 'ruRU', '', 'Любишь путешествовать, $n? Как Искатель Премудрости магистров, я довольно много бываю в дороге. Мне кажется странным, что большинство синдорай так это не любят. Но, впрочем, я не похож на большинство синдорай — мне об этом всегда напоминают.', 24330),
(110115, 'ruRU', '', 'Знаешь ли ты, что в прошлом многие магистры учились среди Кирин-Тора в Даларане? Возможно, пришло время отложить нашу вражду и сражаться с Пылающим Легионом вместе.', 24330),
(110185, 'ruRU', '', 'Жизнь здесь никогда не становится легче.', 24330),
(110252, 'ruRU', '', 'По правде говоря, я немного не вписываюсь в общество. Большинство синдорай довольны тем, что проживают всю свою жизнь в пределах Луносвета. Однако после стольких лет жизни на Дреноре мне там стало душно. Я никогда не умел держать свои мнения при себе...\n\nКогда Великий магистр Роммат попросил меня уйти и стать Искателем Премудрости магистров, это было облегчением для нас обоих. Я намерен выяснить, обладает ли Эмпиреевское Общество чем-то полезным.', 24330),
(110257, 'ruRU', '', 'Они скрытный народ и склонны говорить загадками, так что немногое. Известно, что они ищут по всему миру редкие формы магии для изучения, и этот анклав, возможно, нашёл что-то весьма могущественное.\n\nЯ намерен выяснить, что бы они там ни скрывали.', 24330),
(110259, 'ruRU', '', 'В пещерах Лейхоллоу вспыхнуло заражение лей-червями! Если ты завалишь их туннели тяжёлыми камнями, это поможет сдержать их.', 24330),
(110260, 'ruRU', '', 'Что это?! Один из крупных червей прорывается! Будь готов!', 24330),
(110261, 'ruRU', '', 'Полагаю, это пока остановит их наплыв. Благодарю тебя, защитник.', 24330),
(110293, 'ruRU', '', 'Следи за собой, Андорен. Беллоку не понравилось бы видеть, как ты якшаешься с Альянсом...', 24330),
(110324, 'ruRU', '', 'Сила Титанобоя станет моей!', 24330),
(110327, 'ruRU', '', 'Вы станете свидетелями моего славного восхождения!', 24330),
(110328, 'ruRU', '', 'Да... Я чувствую, как сила Созидателей течёт по моим венам!', 24330),
(110338, 'ruRU', '', 'Вам не остановить меня, глупцы! Мне нужно лишь... больше... силы!', 24330),
(110367, 'ruRU', '', 'Вы не встанете у меня на пути!', 24330),
(110369, 'ruRU', '', 'Твой народ долго принуждал мой народ к рабству. Больше нет! Теперь мы сами кузнецы своей судьбы!', 24330),
(110371, 'ruRU', '', 'Ты была лишь средством для достижения цели. Не более того!', 24330),
(110372, 'ruRU', '', 'Мне не откажут! Я стану богиней-королевой!', 24330),
(110374, 'ruRU', '', 'Узрите мою силу!', 24330),
(110399, 'ruRU', '', 'Ты здесь, чтобы помочь с нашей маленькой "проблемой"?', 24330),
(110400, 'ruRU', '', 'Малдур, тебе не следует разговаривать с Ордой. Не после того, что случилось на Расколотом берегу.', 24330),
(110408, 'ruRU', '', 'Хорошо. Я подготовлю заклинание, которое значительно ослабит Турокса, но мне понадобится твоя помощь, чтобы его повергнуть. Ты готов?', 24330),
(110409, 'ruRU', '', 'Ах, просто нехватка вина в этой части города! Наверняка скоро подойдёт новая партия.', 24330),
(110420, 'ruRU', '', 'Отлично сделано!', 24330),
(110421, 'ruRU', '', 'Очень хорошо.', 24330),
(110422, 'ruRU', '', 'Идеально!', 24330),
(110423, 'ruRU', '', 'Прекрасно!', 24330),
(110424, 'ruRU', '', 'Хорошая работа!', 24330),
(110425, 'ruRU', '', 'Отличная работа!', 24330),
(110426, 'ruRU', '', 'Превосходно!', 24330),
(110427, 'ruRU', '', 'Потренируйся применять свои атаки на этом тренировочном манекене.', 24330),
(110428, 'ruRU', '', 'Теперь, когда у тебя есть все основные атакующие способности, посмотрим, как они работают вместе!', 24330),
(110429, 'ruRU', '', 'Когда почувствуешь себя готовым, изучи свою книгу заклинаний и древо талантов, чтобы найти дополнительные способности, которые можно освоить.', 24330),
(110430, 'ruRU', '', 'Неплохо, но эти демоны не так легко отступят. Будь готов!', 24330),
(110431, 'ruRU', '', 'Ты хорошо усвоил урок! Дальше посмотрим... Погоди, это же...? К оружию! Легион атакует!', 24330),
(110432, 'ruRU', '', 'Хорошая работа! Теперь продемонстрируй своё умение против двух противников одновременно.', 24330),
(110433, 'ruRU', '', 'Тренировка на манекенах окончена, $p. Пора проявить свою отвагу. Объедини все уроки, что ты усвоил, и используй их, чтобы победить моих людей в бою.', 24330),
(110434, 'ruRU', '', 'Инфернал! Используй всю свою подготовку, чтобы одолеть его!', 24330);
